    const total = await this.db.models.orders.countDocuments({}).session(this.session)
    return { items: documents.map(toEntity), total, offset, limit }
  }

  /** Rows with this customer, by primary key. */
  async listByCustomer(customer: number): Promise<Order[]> {
    return (await this.db.models.orders.find({ customer }).sort({ _id: 1 }).session(this.session).lean<Stored[]>()).map(toEntity)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Order): Promise<Order> {
    try {
      const [document] = await this.db.models.orders.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Order', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Order): Promise<Order> {
    try {
      await this.db.models.orders.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Order', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Order): Promise<void> {
    try {
      await this.db.models.orders.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Order', error)
    }
  }

  /** Adds an item to lines, and returns the row as it is then, or null when there is none. */
  async addLine(id: number, line: { product: string; quantity: number }): Promise<Order | null> {
    let changed: Stored | null
    try {
      changed = await this.db.models.orders
        .findOneAndUpdate({ _id: id }, { $push: { lines: line } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Order', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Removes an item from lines that has this size, and returns the row as it is then, or null when there is none. */
  async removeLine(id: number, position: number, size: number): Promise<Order | null> {
    let changed: Stored | null
    try {
      changed = await this.db.models.orders
        .findOneAndUpdate({ _id: id, lines: { $size: size } }, [{ $set: { lines: { $concatArrays: [{ $slice: ['$lines', position] }, { $slice: ['$lines', position + 1, size] }] } } }], { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Order', error)
    }
    return changed === null ? null : toEntity(changed)
  }
}

/** Keeps orders rows in memory, for tests and for trying the services without a database. */
export class MemoryOrderRepository implements OrderRepository {
  private readonly rows = new Map<string, Order>()

  private visible(): Order[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Order | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Order>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Rows with this customer, by primary key. */
  async listByCustomer(customer: number): Promise<Order[]> {
    return this.visible().filter((row) => row.customer === customer)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Order): Promise<Order> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Order): Promise<Order> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Order): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }

  /** Adds an item to lines, and returns the row as it is then, or null when there is none. */
  async addLine(id: number, line: { product: string; quantity: number }): Promise<Order | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.lines = [...(row.lines ?? []), line]
    return row
  }

  /** Removes an item from lines that has this size, and returns the row as it is then, or null when there is none. */
  async removeLine(id: number, position: number, size: number): Promise<Order | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    if ((row.lines ?? []).length !== size) return null
    row.lines = (row.lines ?? []).filter((_, index) => index !== position)
    return row
  }
}

