/** Operations on orders: what each one checks before it writes. */
import { problems, type Rule } from '../documents.js'
import { Order } from '../entities/order.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['id', 'customer', 'status', 'total', 'placedAt', 'lines'])

/** The rules of the documents and lists inside each one */
const DOCUMENTS = {
  lines: { items: { fields: { product: { required: true }, quantity: { required: true } } } },
} satisfies Record<string, Rule>

/** Operations on orders. Each write runs in its own transaction. */
export class OrderService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Order' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.id
      if (value == null) {
        if (creating || 'id' in values) errors.push({ field: '_id', message: 'is required' })
      }
    }
    {
      const value = values.customer
      if (value == null) {
        if (creating || 'customer' in values) errors.push({ field: 'customer', message: 'is required' })
      }
    }
    {
      const value = values.status
      if (value == null) {
        if (creating || 'status' in values) errors.push({ field: 'status', message: 'is required' })
      } else {
        if (!['new', 'paid', 'sent'].includes(value as never)) errors.push({ field: 'status', message: 'must be one of: new, paid, sent' })
      }
    }
    {
      const value = values.total
      if (value == null) {
        if (creating || 'total' in values) errors.push({ field: 'total', message: 'is required' })
      }
    }
    {
      const value = values.placedAt
      if (value == null) {
        if (creating || 'placedAt' in values) errors.push({ field: 'placedAt', message: 'is required' })
      }
    }
    {
      const value = values.lines
      if (value == null) {
        if (creating || 'lines' in values) errors.push({ field: 'lines', message: 'is required' })
      } else {
        errors.push(...problems(value, DOCUMENTS.lines, 'lines'))
      }
    }
    {
      const customer = 'customer' in values ? values.customer : current?.customer
      if (customer != null && (await uow.customers.findById(customer as number)) === null)
        errors.push({ field: 'customer', message: 'no Customer has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Order with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Order> {
    const entity = await uow.orders.findById(id)
    if (entity === null) throw new NotFoundError('Order', id)
    return entity
  }

  /** Stores a new Order after checking it. */
  async createOrder(order: Order): Promise<Order> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (order as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.orders.insert(order)
      return created
    })
  }

  /** The Order with this key; NotFoundError when there is none. */
  async getOrder(id: number): Promise<Order> {
    return await this.find(this.uow, id)
  }

  /** A page of orders, by primary key. */
  async listOrders(offset = 0, limit = 50): Promise<Page<Order>> {
    return this.uow.orders.list(offset, limit)
  }

  /** Changes the given values of a Order. */
  async updateOrder(id: number, changes: Partial<Order>): Promise<Order> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.orders.update(current)
      return updated
    })
  }

  /** Deletes a Order. */
  async deleteOrder(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.orders.delete(current)
    })
  }

  /** The orders with this customer. */
  async listOrdersByCustomer(customer: number): Promise<Order[]> {
    return await this.uow.orders.listByCustomer(customer)
  }

  /** Adds an item to lines. */
  async addLine(id: number, line: { product: string; quantity: number }): Promise<Order> {
    const errors = problems([line], DOCUMENTS.lines, 'lines')
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.orders.addLine(id, line)
      if (updated === null) throw new NotFoundError('Order', id)
      return updated
    })
  }

  /** Removes an item from lines, by its position. */
  async removeLine(id: number, position: number): Promise<Order> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(position in (current.lines ?? []))) throw new NotFoundError('Line', position)
      const updated = await uow.orders.removeLine(id, position, (current.lines ?? []).length)
      if (updated === null) throw new ConflictError('Order', 'was changed by someone else since it was read', ['lines'])
      return updated
    })
  }
}

